import {prepareBackend,moduleFor,render,shell,user as sessionUser,nav} from './test-support.mjs';
await prepareBackend();
// Native D1 integration test. Pass the current synthetic fixture generated by
// test-backup-roundtrip.mjs and set MINIFLARE_MODULE to the installed module URL.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import {fileURLToPath} from 'node:url';
const {Miniflare,convertV4MiniflareOptions}=await import(process.env.MINIFLARE_MODULE || 'miniflare');
const fixture=JSON.parse(fs.readFileSync(process.argv[2],'utf8'));
// Exercise the new persistent diagnostics through the production HTTP handler.
const api=await import('../.tests/backend.mjs');
fixture.storage.tables.find(t=>t.name==='parser_error_daily').rows=[{owner_name:'Eugene',day:'2026-10-23',p1_peak:2,p2_peak:7,first_sample_at:1,last_sample_at:2}];
fixture.storage.tables.find(t=>t.name==='parser_candidate_intakes').rows=[{candidate_token:'synthetic-immutable-intake-token',parser:'apify',source_id:'hh',received_at:'2026-10-23T09:00:00Z'}];
fixture.manifest=fixture.storage.tables.map(t=>({name:t.name,columns:t.columns.map(c=>c.name),rows:t.rows.length}));fixture.integrity.digest=await api.backupDigest(fixture);
const options={cf:false,workers:[{
 name:'test-router',modules:true,d1Databases:{DB:'backup-test'},serviceBindings:{APP:'actual-app'},
 script:`export default {async fetch(request,env){
  const path=new URL(request.url).pathname;
  if(path==='/__test/hosting-migrations') {await env.DB.batch([env.DB.prepare('CREATE TABLE __appgarden_migrations(id INTEGER PRIMARY KEY, name TEXT)'),env.DB.prepare("INSERT INTO __appgarden_migrations VALUES(7,'destination-hosting-migration')")]);return new Response('ok');}
  if(path==='/__test/fail') {await env.DB.prepare("CREATE TRIGGER test_failure BEFORE INSERT ON company_tasks BEGIN SELECT RAISE(ABORT,'injected D1 failure'); END").run();return new Response('ok');}
  if(path==='/__test/clear') {await env.DB.prepare('DROP TRIGGER test_failure').run();return new Response('ok');}
  return env.APP.fetch(request);
 }}`,
 outboundService:()=>new Response('Network disabled',{status:503}),
},{name:'actual-app',modules:true,scriptPath:fileURLToPath(new URL('../.tests/worker.mjs',import.meta.url)),compatibilityDate:'2026-05-15',d1Databases:{DB:'backup-test'},bindings:{SITE_PASSWORD:'local-test',SESSION_SECRET:'local-test-secret'},outboundService:()=>new Response('Network disabled',{status:503})}]};
const mf=new Miniflare(convertV4MiniflareOptions ? convertV4MiniflareOptions(options) : options);
const timer=setTimeout(()=>{console.error('Miniflare test timed out');process.exit(2);},45000);
function canonical(v){if(Array.isArray(v))return v.map(canonical);if(v&&typeof v==='object')return Object.fromEntries(Object.keys(v).sort().map(k=>[k,canonical(v[k])]));return v;}
function records(b){return b.storage.tables.map(t=>({name:t.name,rows:t.rows.map(canonical).sort((a,b)=>JSON.stringify(a).localeCompare(JSON.stringify(b)))})).sort((a,b)=>a.name.localeCompare(b.name));}
try {
 const login=await mf.dispatchFetch('https://test.invalid/auth',{method:'POST',body:new URLSearchParams({login:'Eugene',password:'local-test'}),redirect:'manual'});
 assert.equal(login.status,303);const cookie=login.headers.get('set-cookie').split(';')[0];
 const req=payload=>mf.dispatchFetch('https://test.invalid/api/backup',{method:payload?'POST':'GET',headers:{cookie,'content-type':'application/json'},body:payload?JSON.stringify(payload):undefined});
 const get=async()=>{const r=await req();const body=await r.json();assert.equal(r.status,200,JSON.stringify(body));return body;};
 let r=await mf.dispatchFetch('https://test.invalid/__test/hosting-migrations');assert.equal(r.status,200);
 r=await req(fixture);assert.equal(r.status,200,JSON.stringify(await r.json()));
 const exported=await get();assert.deepEqual(records(exported),records(fixture));assert.deepEqual(exported.metadata.sequences,fixture.metadata.sequences);
 assert.deepEqual(exported.metadata.migrations.find(t=>t.name==='__appgarden_migrations').rows,[{id:7,name:'destination-hosting-migration'}]);
 r=await req(exported);assert.equal(r.status,200,JSON.stringify(await r.json()));assert.deepEqual(records(await get()),records(fixture));
 assert.deepEqual((await get()).metadata.migrations,exported.metadata.migrations,'Hosting migration records survive repeated restoration');
 r=await mf.dispatchFetch('https://test.invalid/__test/fail');assert.equal(r.status,200);
 r=await req(exported);assert.equal(r.status,400,'Injected failure must roll back the entire D1 batch');assert.deepEqual(records(await get()),records(exported));
 assert.deepEqual((await get()).metadata.sequences,exported.metadata.sequences);
 r=await mf.dispatchFetch('https://test.invalid/__test/clear');assert.equal(r.status,200);
 const corrupt=structuredClone(exported);corrupt.storage.tables.find(t=>t.name==='company_identity').rows=[];
 r=await req(corrupt);assert.equal(r.status,400);assert.deepEqual(records(await get()),records(exported));
 console.log(JSON.stringify({runtime:'Miniflare/workerd, local D1',tables:exported.storage.tables.length,rows:exported.storage.tables.reduce((n,t)=>n+t.rows.length,0),emptyDatabaseRestore:true,allValuesEqual:true,sequencesEqual:true,repeatedRestore:true,transactionFailureRollback:true,corruptionRejected:true}));
} finally {clearTimeout(timer);await mf.dispose();}
